package ama.transcript;

import ama.access.MeetingAccess;
import ama.contract.IdentityContracts.Actor;
import ama.contract.TranscriptContracts.*;
import ama.contract.MinutesContracts.Mark;
import ama.model.HttpMaterialEnhancement;
import com.fasterxml.jackson.databind.*;
import org.springframework.jdbc.core.JdbcTemplate;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static ama.contract.MinutesContracts.uuid;

/** Private reviewed proposals, independent from immutable speech checkpoint provenance. */
public final class JdbcMaterialEnhancements {
 private static final ObjectMapper JSON=new ObjectMapper();
 private final JdbcTranscriptAuthority authority;private final JdbcSavedTranscripts saved;private final HttpMaterialEnhancement model;private final JdbcTemplate j;
 public JdbcMaterialEnhancements(JdbcTranscriptAuthority authority,JdbcSavedTranscripts saved,HttpMaterialEnhancement model){this.authority=authority;this.saved=saved;this.model=model;j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(5);}
 private static Failure failure(int status,String code){return new Failure(status,code);}
 private void prepare(Actor actor,String meeting){uuid(meeting);authority.savedAccess().prepareExternalRead(actor,meeting);}
 private void gate(Actor actor,String meeting){authority.fileRegistry().lock(actor,meeting,MeetingAccess.Action.EDIT);}
 private Map<String,Object> root(String meeting){return j.queryForMap("SELECT id,revision,transcript_revision_id,material_snapshot_id,materials_pending,ever_published,lifecycle,governance_state FROM meeting WHERE id=?",meeting);}
 private boolean matches(Map<String,Object> r,long revision,String source,String snapshot){
  if(((Number)r.get("revision")).longValue()!=revision||!Objects.equals(snapshot,r.get("material_snapshot_id"))||((Number)r.get("materials_pending")).intValue()!=0||((Number)r.get("ever_published")).intValue()!=0||!"ACTIVE".equals(r.get("lifecycle"))||!"ACTIVE".equals(r.get("governance_state")))return false;
  if(r.get("transcript_revision_id")!=null)return source.equals(r.get("transcript_revision_id"));
  // The first RAW result is an immutable task output. The current pointer is
  // intentionally absent until the first WORKING save; require its exact fence.
  return j.queryForObject("SELECT COUNT(*) FROM transcript_revision r JOIN durable_task t ON t.id=r.producer_task_id WHERE r.id=? AND r.meeting_id=? AND r.kind='RAW' AND t.subject_id=r.meeting_id AND t.subject_kind='MEETING' AND t.task_type='TRANSCRIPT_IMPORT_V1' AND t.state='SUCCEEDED' AND t.output_kind='TRANSCRIPT_REVISION' AND t.output_id=r.id AND t.business_version=?",Integer.class,source,r.get("id"),revision)==1;
 }
 private void current(String meeting,long revision,String source,String snapshot){if(!matches(root(meeting),revision,source,snapshot))throw failure(409,"ENHANCEMENT_SOURCE_CHANGED");}
 private List<Map<String,Object>> rows(String clause,Object...args){return j.queryForList("SELECT id,meeting_id,actor_id,request_key,expected_revision,source_revision_id,material_snapshot_id,profile_sha256,IF(OCTET_LENGTH(input_body)<=4194304,input_body,NULL) input_body,IF(OCTET_LENGTH(source_body)<=4194304,source_body,NULL) source_body,IF(OCTET_LENGTH(output_body)<=4194304,output_body,NULL) output_body,decision_key,IF(OCTET_LENGTH(receipt_body)<=8388608,receipt_body,NULL) receipt_body FROM material_enhancement_candidate WHERE "+clause+" LIMIT 1",args);}
 private Map<String,Object> candidate(Actor actor,String meeting,String id){var rows=rows("id=? AND meeting_id=? AND actor_id=?",id,meeting,actor.enterpriseId());if(rows.isEmpty())throw failure(404,"ENHANCEMENT_NOT_FOUND");return rows.getFirst();}
 private Map<String,Object> existing(Actor actor,String meeting,String key,long revision,String source,String snapshot){var rows=rows("meeting_id=? AND actor_id=? AND request_key=?",meeting,actor.enterpriseId(),key);if(rows.isEmpty())return null;var row=rows.getFirst();if(((Number)row.get("expected_revision")).longValue()!=revision||!source.equals(row.get("source_revision_id"))||!Objects.equals(snapshot,row.get("material_snapshot_id")))throw failure(409,"IDEMPOTENCY_CONFLICT");return row;}
 public Map<String,Object> generate(Actor actor,String meeting,String key,long revision,String source,String snapshot){return generate(actor,meeting,key,revision,source,snapshot,false);}
 Map<String,Object> generateInitial(Actor actor,String meeting,String key,long revision,String source,String snapshot){return generate(actor,meeting,key,revision,source,snapshot,true);}
 private Map<String,Object> generate(Actor actor,String meeting,String key,long revision,String source,String snapshot,boolean initial){
  uuid(key);uuid(source);if(snapshot!=null)uuid(snapshot);if(revision<0)throw new IllegalArgumentException("Revision required");prepare(actor,meeting);
  var existing=authority.transactionRunner().required(()->{gate(actor,meeting);return existing(actor,meeting,key,revision,source,snapshot);});
  if(existing!=null)return execute(actor,meeting,existing);
  var full=saved.readOwner(actor,meeting,source);var original=JSON.valueToTree(full).path("selected");
  if(!(initial?"RAW":"WORKING").equals(original.path("kind").asText())||!JSON.valueToTree(full).path("capabilities").path("canSave").asBoolean())throw failure(409,"ENHANCEMENT_SOURCE_CHANGED");
  var materialRows=authority.transactionRunner().required(()->{gate(actor,meeting);current(meeting,revision,source,snapshot);if(snapshot==null)return List.<Map<String,Object>>of();var materials=j.queryForList("SELECT r.id revision_id,r.content_hash,d.text_file_id FROM material_snapshot_item i JOIN material_revision r ON r.id=i.material_revision_id JOIN material_reference m ON m.id=r.reference_id JOIN parsed_document d ON d.material_revision_id=r.id WHERE i.snapshot_id=? AND m.meeting_id=? AND (?=1 OR m.state='ACTIVE') AND r.parse_state='READY' AND d.state='READY' ORDER BY i.ordinal LIMIT 17",snapshot,meeting,initial?1:0);if(materials.isEmpty()||materials.size()>16)throw failure(413,"ENHANCEMENT_MATERIAL_LIMIT");return materials;});
  var input=JSON.createObjectNode().put("profile",HttpMaterialEnhancement.PROFILE).put("meetingId",meeting).put("sourceRevisionId",source).put("expectedRevisionToken",Long.toString(revision));if(snapshot==null)input.putNull("materialSnapshotId");else input.put("materialSnapshotId",snapshot);
  var segments=input.putArray("segments");long sourceSize=0;for(var segment:original.path("segments")){String text=segment.path("body").asText();sourceSize+=text.length();if(text.length()>65536||sourceSize>1048576)throw failure(413,"ENHANCEMENT_SOURCE_LIMIT");segments.addObject().put("id",segment.path("segmentId").asText()).put("text",text);}if(segments.isEmpty()||segments.size()>4096)throw failure(413,"ENHANCEMENT_SOURCE_LIMIT");
  var materials=input.putArray("materials");long characters=0;
  for(var material:materialRows){try(var download=authority.fileRegistry().download(actor,(String)material.get("text_file_id"),null)){
   if(!meeting.equals(download.file().meetingId())||download.length()>1048576)throw failure(413,"ENHANCEMENT_MATERIAL_LIMIT");byte[] bytes=download.body().readNBytes(1048577);if(bytes.length!=download.length()||!HttpMaterialEnhancement.sha(bytes).equals(download.file().sha256()))throw failure(503,"MATERIAL_BYTES_UNAVAILABLE");String text=StandardCharsets.UTF_8.newDecoder().decode(java.nio.ByteBuffer.wrap(bytes)).toString();characters+=text.length();if(characters>262144)throw failure(413,"ENHANCEMENT_MATERIAL_LIMIT");var units=materials.addObject().put("revisionId",(String)material.get("revision_id")).put("sha256",(String)material.get("content_hash")).putArray("units");int offset=0,ordinal=1;while(offset<text.length()){int end=Math.min(offset+65536,text.length());if(end<text.length()&&Character.isHighSurrogate(text.charAt(end-1)))end--;units.addObject().put("ordinal",ordinal++).put("text",text.substring(offset,end));offset=end;}
  }catch(java.io.IOException unavailable){throw failure(503,"MATERIAL_BYTES_UNAVAILABLE");}}
  String inputBody=encode(input),sourceBody=encode(original);if(inputBody.getBytes(StandardCharsets.UTF_8).length>HttpMaterialEnhancement.MAX_BYTES||sourceBody.getBytes(StandardCharsets.UTF_8).length>HttpMaterialEnhancement.MAX_BYTES)throw failure(413,"ENHANCEMENT_SOURCE_LIMIT");
  prepare(actor,meeting);var stored=authority.transactionRunner().required(()->{gate(actor,meeting);var replay=existing(actor,meeting,key,revision,source,snapshot);if(replay!=null)return replay;current(meeting,revision,source,snapshot);if(j.queryForObject("SELECT COUNT(*) FROM material_enhancement_candidate WHERE meeting_id=?",Integer.class,meeting)>=64)throw failure(422,"ENHANCEMENT_HISTORY_LIMIT");String id=UUID.randomUUID().toString();j.update("INSERT INTO material_enhancement_candidate(id,meeting_id,actor_id,request_key,expected_revision,source_revision_id,material_snapshot_id,profile_sha256,input_body,source_body,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP(6))",id,meeting,actor.enterpriseId(),key,revision,source,snapshot,HttpMaterialEnhancement.PROFILE_SHA256,inputBody,sourceBody);return candidate(actor,meeting,id);});return execute(actor,meeting,stored);
 }
 private Map<String,Object> execute(Actor actor,String meeting,Map<String,Object> row){
  String id=(String)row.get("id");if(row.get("output_body")!=null)return read(actor,meeting,id);
  prepare(actor,meeting);authority.transactionRunner().required(()->{gate(actor,meeting);current(meeting,((Number)row.get("expected_revision")).longValue(),(String)row.get("source_revision_id"),(String)row.get("material_snapshot_id"));return null;});
  if(!HttpMaterialEnhancement.PROFILE_SHA256.equals(row.get("profile_sha256")))throw failure(503,"ENHANCEMENT_PROFILE_UNAVAILABLE");JsonNode result;
  try{result=model.execute(id,body(row,"input_body").getBytes(StandardCharsets.UTF_8));}catch(HttpMaterialEnhancement.RejectedInput rejected){throw failure(422,"ENHANCEMENT_INPUT_REJECTED");}catch(java.io.IOException|IllegalArgumentException unavailable){throw failure(503,"ENHANCEMENT_RETRY_SAME_REQUEST");}
  prepare(actor,meeting);authority.transactionRunner().required(()->{gate(actor,meeting);current(meeting,((Number)row.get("expected_revision")).longValue(),(String)row.get("source_revision_id"),(String)row.get("material_snapshot_id"));j.update("UPDATE material_enhancement_candidate SET output_body=? WHERE id=? AND output_body IS NULL",encode(result),id);return null;});return read(actor,meeting,id);
 }
 private boolean appliesAdjustment(String meeting,String id){return j.queryForObject("SELECT EXISTS(SELECT 1 FROM material_adjustment WHERE meeting_id=? AND candidate_id=? AND stage='READY')",Integer.class,meeting,id)==1;}
 public Map<String,Object> read(Actor actor,String meeting,String id){uuid(id);prepare(actor,meeting);return authority.transactionRunner().required(()->{gate(actor,meeting);var row=candidate(actor,meeting,id);var result=new LinkedHashMap<String,Object>();result.put("candidateId",id);result.put("sourceRevisionId",row.get("source_revision_id"));result.put("materialSnapshotId",row.get("material_snapshot_id"));result.put("expectedRevisionToken",row.get("expected_revision").toString());result.put("profile",HttpMaterialEnhancement.PROFILE);boolean current=matches(root(meeting),((Number)row.get("expected_revision")).longValue(),(String)row.get("source_revision_id"),(String)row.get("material_snapshot_id"));String state=row.get("receipt_body")!=null?"APPLIED":row.get("decision_key")!=null?"APPLYING":!current?"STALE":row.get("output_body")==null?"PENDING":"READY";result.put("state",state);if(current&&row.get("output_body")!=null&&row.get("decision_key")==null){var original=parse(body(row,"source_body"));var output=verify(row);var changes=JSON.createArrayNode();for(int n=0;n<output.path("segments").size();n++){var before=original.path("segments").get(n);var after=output.path("segments").get(n);if(!before.path("body").asText().equals(after.path("text").asText()))changes.addObject().put("segmentId",after.path("id").asText()).put("before",before.path("body").asText()).put("after",after.path("text").asText());}result.put("changes",changes);boolean refresh=changes.isEmpty()&&appliesAdjustment(meeting,id);if(refresh)result.put("materialRefresh",true);result.put("canApply",refresh||!changes.isEmpty());}return result;});}
 public Map<String,Object> adopt(Actor actor,String meeting,String id,String decision){return adopt(actor,meeting,id,decision,false);}
 Map<String,Object> adoptInitial(Actor actor,String meeting,String id,String decision){return adopt(actor,meeting,id,decision,true);}
 private Map<String,Object> adopt(Actor actor,String meeting,String id,String decision,boolean initial){uuid(id);uuid(decision);prepare(actor,meeting);
  var row=authority.transactionRunner().required(()->{gate(actor,meeting);var selected=candidate(actor,meeting,id);if(selected.get("decision_key")!=null){if(!decision.equals(selected.get("decision_key")))throw failure(409,"IDEMPOTENCY_CONFLICT");return selected;}current(meeting,((Number)selected.get("expected_revision")).longValue(),(String)selected.get("source_revision_id"),(String)selected.get("material_snapshot_id"));if(selected.get("output_body")==null)throw failure(409,"ENHANCEMENT_NOT_READY");var output=verify(selected);var original=parse(body(selected,"source_body"));boolean changed=false;for(int n=0;n<output.path("segments").size();n++)changed|=!output.path("segments").get(n).path("text").asText().equals(original.path("segments").get(n).path("body").asText());if(!changed&&!initial&&!appliesAdjustment(meeting,id))throw failure(422,"ENHANCEMENT_NO_CHANGES");j.update("UPDATE material_enhancement_candidate SET decision_key=? WHERE id=?",decision,id);return candidate(actor,meeting,id);});
  var original=parse(body(row,"source_body"));var output=verify(row);var edits=new ArrayList<Edit>();boolean changed=false;for(int n=0;n<output.path("segments").size();n++){var before=original.path("segments").get(n);var after=output.path("segments").get(n);var marks=new ArrayList<Mark>();for(var mark:before.path("marks"))marks.add(Mark.valueOf(mark.asText()));String text=after.path("text").asText();changed|=!text.equals(before.path("body").asText());edits.add(new Edit(after.path("id").asText(),text,marks));}if(!changed&&!initial&&!appliesAdjustment(meeting,id))throw failure(422,"ENHANCEMENT_NO_CHANGES");
  var command=new Command(Operation.SAVE,((Number)row.get("expected_revision")).longValue(),(String)row.get("source_revision_id"),edits);
  var receipt=saved.mutate(actor,meeting,decision,command,UUID.randomUUID().toString());prepare(actor,meeting);authority.transactionRunner().required(()->{gate(actor,meeting);j.update("UPDATE material_enhancement_candidate SET receipt_body=? WHERE id=? AND decision_key=?",encode(receipt),id,decision);return null;});return receipt;
 }
 private static JsonNode verify(Map<String,Object> row){if(!HttpMaterialEnhancement.PROFILE_SHA256.equals(row.get("profile_sha256")))throw failure(503,"ENHANCEMENT_PROFILE_UNAVAILABLE");return HttpMaterialEnhancement.verify((String)row.get("id"),body(row,"input_body").getBytes(StandardCharsets.UTF_8),body(row,"output_body").getBytes(StandardCharsets.UTF_8));}
 private static String body(Map<String,Object> row,String key){if(!(row.get(key) instanceof String body))throw failure(503,"ENHANCEMENT_RECORD_UNAVAILABLE");return body;}
 private static JsonNode parse(String body){try{return JSON.readTree(body);}catch(java.io.IOException invalid){throw failure(503,"ENHANCEMENT_RECORD_UNAVAILABLE");}}
 private static String encode(Object value){try{return JSON.writeValueAsString(value);}catch(java.io.IOException invalid){throw failure(503,"ENHANCEMENT_RECORD_UNAVAILABLE");}}
}
